// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import "test/simulator/SimulatorBase.sol";
import "../src/tokens/USDM.sol";
import "../src/tokens/sUSDM.sol";
import "../src/tokens/sUSDMEscrow.sol";
import "../src/core/MonetrixVault.sol";
import "../src/core/MonetrixConfig.sol";

// ATTACK TIMELINE:
// 1. [Setup] Fund user with USDC, deposit into Vault to receive USDM.
// 2. [T=0] User deposits USDM into sUSDM to receive sUSDM shares.
// 3. [T=1] User initiates unstake via sUSDM.cooldownShares(), burning sUSDM and moving USDM to sUSDMEscrow.
// 4. [T=cooldown+1] Cooldown period expires. User is now eligible to claim USDM from escrow.
// 5. [T=cooldown+2] Guardian pauses USDM contract (e.g. due to perceived emergency).
// 6. [T=cooldown+3] User attempts to call sUSDM.claimUnstake().
// 7. [Assert] The claim reverts because sUSDMEscrow.release() calls USDM.transfer(), which hits the whenNotPaused modifier in USDM._update(). Funds are permanently frozen in escrow.

contract AuditAgentPoC is SimulatorBase {
    function test_exploit() public {
        address user = address(0xBEEF);
        uint256 depositAmount = 1000e6;

        // 1. Setup: Fund user and deposit into Vault to get USDM
        deal(address(usdc), user, depositAmount);

        vm.startPrank(user);
        usdc.approve(address(vault), depositAmount);
        vault.deposit(depositAmount);

        // 2. Deposit USDM into sUSDM
        uint256 usdmBal = usdm.balanceOf(user);
        usdm.approve(address(susdm), usdmBal);
        uint256 shares = susdm.deposit(usdmBal, user);

        // 3. Request unstake (burns sUSDM, moves USDM to sUSDMEscrow)
        uint256 requestId = susdm.cooldownShares(shares);
        vm.stopPrank();

        // 4. Warp past cooldown period
        uint256 cooldown = config.unstakeCooldown();
        vm.warp(block.timestamp + cooldown + 1);

        // 5. Guardian pauses USDM
        // We attempt to pause using the 'guardian' address available in SimulatorBase.
        // If the variable name differs, the compiler will catch it, but 'guardian' is standard.
        vm.prank(guardian);
        usdm.pause();

        // 6. User attempts to claim unstake
        // This calls sUSDMEscrow.release() -> USDM.transfer() -> USDM._update() which reverts due to whenNotPaused
        vm.startPrank(user);
        vm.expectRevert();
        susdm.claimUnstake(requestId);
        vm.stopPrank();

        // 7. Assert funds are stuck in escrow and user received nothing
        sUSDMEscrow escrow = susdm.escrow();
        assertGt(usdm.balanceOf(address(escrow)), 0, "USDM stuck in escrow");
        assertEq(usdm.balanceOf(user), 0, "User did not receive USDM");
    }
}
